/* Schede riutilizzate (alias) dentro la configurazione base: stessi dati, usati in piu' punti. */
(function () {
  const S = W.SCHEDE;
  const BASE = 'monotrave-donati';
  const ALIAS = [   // [dove compare, scheda di origine]
    ['quadro-gru-festoni-carrello.pdf', 'derivazione-carrello-festoni-carrello.pdf'],  // quadro elettrico gru > festoni carrello
    ['motori-ponte.pdf',                'quadro-gru-motori-ponte.pdf'],                // menu > motori ponte
    ['motore-carrello.pdf',             'derivazione-carrello-motore-carrello.pdf']    // menu > motore carrello
  ];
  W.ALIAS_SCHEDE = ALIAS;
  ALIAS.forEach(([a, da]) => { S[BASE + '/' + a] = Object.assign({}, S[BASE + '/' + da], { pdf: da, fonte: BASE + '/' + da }); });
  Object.keys(S).forEach(k => { if (!S[k].fonte) S[k].fonte = k; });
})();

/* Scelta del tipo di carrello: si fa all'inizio (domanda 3) e vale per tutte le schede che hanno varianti ("solo": 'singola' | 'doppia'). */
W.SCELTA_CARRELLO = { id: 'carrello', domanda: 'TIPO DI CARRELLO', opzioni: [['singola', 'CARRELLO A SINGOLA VELOCITÀ'], ['doppia', 'CARRELLO A DOPPIA VELOCITÀ']] };

/* Monotrave Donati - festone pulsantiera: due varianti in base al carrello (solo il filo 13 cambia).
   Le altre configurazioni restano come prima finche' non vengono aggiornate. */
(function () {
  const chiave = 'monotrave-donati/quadro-gru-festone-pulsantiera.pdf';
  const fili = f13 => [['1', '1'], ['2', '4'], ['3', '3'], ['4', '6'], ['5', '68'], ['6', '72'], ['7', '64'], ['8', '7'],
    ['9', '23'], ['10', '15'], ['11', '168'], ['12', '169'], ['13', f13],
    ['14', 'NC'], ['15', 'NC'], ['16', 'NC'], ['17', 'NC'], ['PE', 'PE']];
  const blocco = f13 => [{ tipo: 'fili', cavo: '18G1,5', colonne: ['N° FILO', 'N° SCHEMA'], fili: fili(f13) }];
  W.SCHEDE[chiave] = {
    titolo: 'FESTONE PULSANTIERA',
    sezioni: [
      { tab: 'FESTONE PULSANTIERA', solo: 'singola', blocchi: blocco('NC') },
      { tab: 'FESTONE PULSANTIERA', solo: 'doppia', blocchi: blocco('162') }
    ],
    scelta: W.SCELTA_CARRELLO,
    fonte: chiave
  };
})();

/* Monotrave Donati - finecorsa ponte: l'operaio sceglie come sono montati AVANTI e INDIETRO e vede solo lo schema giusto.
   Contatti fissi (N° schema): stop avanti 88-89 · rallentamento avanti 15-31 · stop indietro 91-92 · rallentamento indietro 31-90.
   Con la fotocellula il rallentamento di quel movimento va sempre ponticellato; con il finecorsa a croce il rallentamento e' sempre presente.
   Croce a 2 scatti: N° filo ancora da inserire ('—'), si possono compilare dalla modalita' modifica. */
(function () {
  const chiave = 'monotrave-donati/quadro-gru-finecorsa-ponte.pdf';
  const foto = (com, no, rall) => ({ tipo: 'fili', tipologia: 'FOTOCELLULA', cavo: '4 x 0,75',
    fili: [['Marrone', '3', '~'], ['Giallo', '2', '~'], ['Bianco', com, 'COM'], ['Verde', no, 'NO']],
    avviso: 'Ponticellare ' + rall + ' in morsettiera' });
  const croce2 = (rallNome, stopNome, rall, stop, dir, sr, ss) => ({ tipo: 'carte', carte: [
    { sigla: sr[0], nome: rallNome, dir, scatto: '1° scatto', fili: [['—', rall[0]], ['—', rall[1]]] },
    { sigla: ss[0], nome: stopNome, dir, scatto: '2° scatto', fili: [['—', stop[0]], ['—', stop[1]]] }] });
  W.SCHEDE[chiave] = {
    titolo: 'FINECORSA PONTE',
    sezioni: [{ tab: 'FINECORSA PONTE', blocchi: [{
      tipo: 'finecorsa',
      fotocellula: { avanti: foto('88', '89', '15 e 31'), indietro: foto('91', '92', '31 e 90') },
      croce2: {
        avanti: croce2('Rall. Avanti', 'Stop Avanti', ['15', '31'], ['88', '89'], 'avanti', 'A', 'B'),
        indietro: croce2('Rall. Indietro', 'Stop Indietro', ['31', '90'], ['91', '92'], 'indietro', 'C', 'D')
      },
      croce4: {
        avanti: { tipo: 'carte', carte: [
          { sigla: 'A', nome: 'Rall. Avanti', dir: 'avanti', scatto: '1° scatto senso orario',  fili: [['1', '15'], ['2', '31']] },
          { sigla: 'B', nome: 'Stop Avanti',  dir: 'avanti', scatto: '2° scatto senso orario',  fili: [['5', '88'], ['6', '89']] }] },
        indietro: { tipo: 'carte', carte: [
          { sigla: 'C', nome: 'Rall. Indietro', dir: 'indietro', scatto: '1° scatto senso antiorario', fili: [['3', '31'], ['4', '90']] },
          { sigla: 'D', nome: 'Stop Indietro',  dir: 'indietro', scatto: '2° scatto senso antiorario', fili: [['7', '91'], ['8', '92']] }] }
      }
    }] }],
    fonte: chiave
  };
})();

/* Monotrave Donati - festoni carrello: prima si sceglie il tipo di carrello (singola o doppia velocita'), poi si vedono
   ALIMENTAZIONE QUADRO DONATI e gli AUSILIARI CARRELLO della variante scelta.
   Singola velocita': il filo 9 (schema 109) non si collega -> NC. Doppia velocita': come prima.
   Si modifica "sul posto" l'elenco delle tab, cosi' vale anche per la voce di QUADRO ELETTRICO GRU (stessi dati). */
(function () {
  const S = W.SCHEDE;
  const d = S['monotrave-donati/derivazione-carrello-festoni-carrello.pdf'];
  const i = d.sezioni.findIndex(s => s.tab === 'AUSILIARI CARRELLO');
  const doppia = d.sezioni[i];
  const singola = JSON.parse(JSON.stringify(doppia));
  singola.solo = 'singola'; doppia.solo = 'doppia';
  const riga = singola.blocchi[0].fili.find(f => f[0] === '9');
  riga[1] = 'NC'; riga[2] = '';
  d.sezioni.splice(i, 1, singola, doppia);
  const scelta = W.SCELTA_CARRELLO;
  d.scelta = scelta;
  S['monotrave-donati/quadro-gru-festoni-carrello.pdf'].scelta = scelta;   // la voce di QUADRO ELETTRICO GRU usa gli stessi dati
})();

/* Monotrave Donati - derivazione comandi: stessa scelta del carrello (singola/doppia velocita') delle altre schede.
   Il filo 13 (schema 162) si collega solo con il carrello a doppia velocita'. Singola: pin 13 NC sulla presa Carpel, assente in radiocomando e
   trasformazione Donati, nessun VELOCE su DESTRA e SINISTRA della Telemecanique.
   Ogni tab esiste in due varianti; i riquadri rossi con l'asterisco non servono piu'. */
(function () {
  const d = W.SCHEDE['monotrave-donati/derivazione-comandi.pdf'];
  const nuove = [];
  d.sezioni.forEach(sez => ['singola', 'doppia'].forEach(v => {
    const c = JSON.parse(JSON.stringify(sez)); c.solo = v;
    c.blocchi.forEach(b => {
      delete b.avvisi;
      if (b.tipo === 'connettore') {
        if (sez.tab === 'PULSANTIERA CARPEL') b.pins.forEach(x => {   // la presa a 16 poli resta completa: il pin 13 e' NC con la singola
          if (x[0] !== 13) return;
          if (v === 'singola') { x[1] = ''; x[2] = 'NC'; }
          else { x[1] = String(x[1]).replace('*', ''); x[2] = String(x[2]).replace('*', ''); }
        });
        else if (v === 'singola') b.pins = b.pins.filter(x => x[0] !== 13);   // radiocomando e trasformazione Donati: senza pin 13
        else b.pins.forEach(x => { if (x[0] === 13) { x[1] = String(x[1]).replace('*', ''); x[2] = String(x[2]).replace('*', ''); } });
      }
      if (b.tipo === 'pulsantiera' && v === 'singola') b.tasti.forEach(t => { t.righe = t.righe.filter(r => r[2][0] !== '13'); });   // destra e sinistra: niente VELOCE
    });
    nuove.push(c);
  }));
  d.sezioni = nuove;
  d.scelta = W.SCHEDE['monotrave-donati/derivazione-carrello-festoni-carrello.pdf'].scelta;
})();

/* Altre configurazioni: partono da una COPIA INDIPENDENTE delle schede del monotrave donati, ULTIMA VERSIONE (con tutte le modifiche sopra).
   Stessi valori all'inizio; poi ognuna si modifica per conto suo. Questo blocco deve restare in fondo al file. */
(function () {
  const S = W.SCHEDE, ALIAS = W.ALIAS_SCHEDE;
  const clona = o => (typeof structuredClone === 'function' ? structuredClone(o) : JSON.parse(JSON.stringify(o)));
  const BASE = 'monotrave-donati';
  const ALTRE = ['monotrave-misia-conico', 'monotrave-misia-cilindrico', 'bitrave-donati', 'bitrave-misia-conico', 'bitrave-misia-cilindrico'];
  const alias = ALIAS.map(x => x[0]);
  const base = {};
  Object.keys(S).filter(k => k.startsWith(BASE + '/')).forEach(k => { const f = k.slice(BASE.length + 1); if (!alias.includes(f)) base[f] = S[k]; });
  ALTRE.forEach(c => {
    const cp = clona(base);
    Object.keys(cp).forEach(f => { delete cp[f].fonte; S[c + '/' + f] = cp[f]; });
    ALIAS.forEach(([a, da]) => { S[c + '/' + a] = Object.assign({}, S[c + '/' + da], { pdf: da, fonte: c + '/' + da }); });
  });
  Object.keys(S).forEach(k => { if (!S[k].fonte) S[k].fonte = k; });
})();

/* Monotrave Misia (motore conico) - QUADRO ELETTRICO GRU: modifiche specifiche.
   La scheda FESTONI diventa FESTONI PARANCO e smette di condividere i dati con QUADRO DERIVAZIONE CARRELLO (che resta com'e').
   Tab: POTENZA SOLLEVAMENTO LENTO / VELOCE, POTENZA CARRELLO (stessa tabella dell'alimentazione) e AUSILIARI PARANCO (senza divisione singola/doppia). */
(function () {
  const S = W.SCHEDE, C = 'monotrave-misia-conico/', k = C + 'quadro-gru-festoni-carrello.pdf';
  const src = S[C + 'derivazione-carrello-festoni-carrello.pdf'];
  const sezioni = JSON.parse(JSON.stringify(src.sezioni));
  const ali = sezioni.find(x => x.tab === 'ALIMENTAZIONE QUADRO DONATI');
  const nome = (x, n) => { const c = JSON.parse(JSON.stringify(x)); c.tab = n; return c; };
  const aus = sezioni.find(x => x.tab === 'AUSILIARI CARRELLO' && x.solo === 'doppia');
  delete aus.solo; aus.tab = 'AUSILIARI PARANCO';
  S[k] = { titolo: 'FESTONI PARANCO', voce: 'FESTONI PARANCO', sezioni: [
    nome(ali, 'POTENZA SOLLEVAMENTO LENTO'), nome(ali, 'POTENZA SOLLEVAMENTO VELOCE'), nome(ali, 'POTENZA CARRELLO'), aus
  ], fonte: k };
})();


/* Monotrave Misia (motore conico): la colonna MORSETTO DONATI non serve piu' -> tolta da tutte le tabelle a fili (titolo e valori).
   Resta solo nella tabella a carte del FINECORSA CARRELLO, dove e' l'unica informazione accanto al N° filo. */
(function () {
  const S = W.SCHEDE, visti = new Set();
  Object.keys(S).filter(k => k.startsWith('monotrave-misia-conico/')).forEach(k => {
    const d = S[k];
    if (visti.has(d.sezioni)) return; visti.add(d.sezioni);
    d.sezioni.forEach(s => s.blocchi.forEach(b => {
      if (b.tipo !== 'fili' || !b.colonne) return;
      const i = b.colonne.findIndex(c => /MORSETTO DONATI/i.test(c));
      if (i < 0) return;
      b.colonne.splice(i, 1);
      b.fili.forEach(f => f.splice(i, 1));
    }));
  });
})();

