/* Monotrave Misia (motore conico): nuove schede nel menu principale e derivazione comandi senza TRASF. PULSANTIERA DONATI. */
(function () {
  const S = W.SCHEDE, C = 'monotrave-misia-conico/';
  const copia = o => JSON.parse(JSON.stringify(o));
  // MOTORE SOLLEVAMENTO: come MOTORE CARRELLO a doppia velocita', ma su una pagina sola (lenta sopra, veloce sotto)
  const mc = S[C + 'derivazione-carrello-motore-carrello.pdf'].sezioni.find(x => x.tab === 'MOTORE A DOPPIA VELOCITÀ');
  const blocchi = copia(mc.blocchi);
  blocchi[0].titolo = 'CAVO ALIMENTAZIONE MOTORE SOLLEVAMENTO';
  let k = C + 'motore-sollevamento.pdf';
  S[k] = { titolo: 'MOTORE SOLLEVAMENTO', sezioni: [{ tab: 'MOTORE SOLLEVAMENTO', blocchi }], fonte: k };
  // FINECORSA SOLLEVAMENTO e LIMITATORE DI CARICO: copie di FINECORSA CARRELLO
  const fc = S[C + 'derivazione-carrello-finecorsa-carrello.pdf'];
  [['finecorsa-sollevamento.pdf', 'FINECORSA SOLLEVAMENTO'], ['limitatore-di-carico.pdf', 'LIMITATORE DI CARICO']].forEach(([f, nome]) => {
    const c = copia(fc); c.titolo = nome; c.sezioni.forEach(x => { x.tab = nome; });
    k = C + f; c.fonte = k; S[k] = c;
  });
  // DERIVAZIONE COMANDI: via TRASF. PULSANTIERA DONATI (entrambe le varianti)
  const dc = S[C + 'derivazione-comandi.pdf'];
  dc.sezioni = dc.sezioni.filter(x => x.tab !== 'TRASF. PULSANTIERA DONATI');
})();

