const _blob = {};
function blobUrl(u) {
  if (!u || u.slice(0, 5) !== 'data:') return u;
  if (_blob[u]) return _blob[u];
  const p = u.split(','), mime = (p[0].match(/:(.*?);/) || [0, 'image/jpeg'])[1], bin = atob(p[1]), a = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i);
  return (_blob[u] = URL.createObjectURL(new Blob([a], { type: mime })));
}
